        speed = Max(run, maxSpeed);
        Running = true;
    } else {
        Running = false;
        if (gap <= followRange)
            speed = 0.0f;
        else if (gap < half)
            speed = targetSpeed * 0.8f;
        else
            speed = targetSpeed;
    }
