    long offset = 0;
    for (long i = 0; i < ParentClass->Rounds[ParentClass->CurrentRound].Waves[ParentClass->CurrentWave].Count; ++i, offset += sizeof(SArenaEnemyEntry)) {
        if (IsActiveThreadTerminating()) return;
        SArenaEnemyEntry* enemies = ParentClass->Rounds[ParentClass->CurrentRound].Waves[ParentClass->CurrentWave].Enemies;
        bool same = ((SArenaEnemyEntry*)((char*)enemies + offset))->Name == Me.GetDefName();
        if (same) {
            if (IsActiveThreadTerminating()) return;
            EnemyIndex = i;
        }
    }
    if (IsActiveThreadTerminating()) return;
    Game->EntitySetInFaction(Me, "FACTION_MONSTERS");
    HasHealthBar = false;
    bool isEarthTroll = Me.GetDefName() == "CREATURE_EARTH_TROLL_START_STANDING";
    if (isEarthTroll) {
        if (IsActiveThreadTerminating()) return;
        HealthBar = Game->AddQuestInfoBarHealth(Me, CRGBColour(255, 255, 0, 255), "HUD_QUEST_ICON_EARTH_TROLL", 1.0f);
        HasHealthBar = true;
    } else {
        bool isRockTroll = Me.GetDefName() == "CREATURE_ROCK_TROLL_START_STANDING";
        if (isRockTroll) {
            if (IsActiveThreadTerminating()) return;
            HealthBar = Game->AddQuestInfoBarHealth(Me, CRGBColour(255, 255, 0, 255), "HUD_QUEST_ICON_ROCK_TROLL", 1.0f);
            HasHealthBar = true;
        } else {
            bool isScorpionKing = Me.GetDefName() == "CREATURE_SCORPION_KING";
            if (isScorpionKing) {
                if (IsActiveThreadTerminating()) return;
                HealthBar = Game->AddQuestInfoBarHealth(Me, CRGBColour(255, 255, 0, 255), "HUD_QUEST_ICON_SCORPION_KING", 1.0f);
                HasHealthBar = true;
            }
        }
    }
    if (IsActiveThreadTerminating()) return;
    do {
        if (Me.MsgIsHitByWithFlourish("SCRIPT_NAME_HERO")) {
            if (IsActiveThreadTerminating()) return;
            if (ParentClass->CrowdTimer.GetTime() <= 0) {
                if (IsActiveThreadTerminating()) return;
