                g_pGameScriptInterface->SetTimer(ParentClass->CrowdTimer.ID, 10);
                ParentClass->Score += 5;
            }
        } else if (Me.MsgIsHitByWithDecapitate("SCRIPT_NAME_HERO")) {
            if (IsActiveThreadTerminating()) return;
            if (ParentClass->CrowdTimer.GetTime() <= 8) {
                if (IsActiveThreadTerminating()) return;
                Game->PlayCriteriaSoundOnThing(Game->GetNearestWithScriptName(Game->GetHero(), "ArenaSpawn"), ParentClass->CrowdSounds[ParentClass->CrowdSoundIndex].Criteria);
                g_pGameScriptInterface->SetTimer(ParentClass->CrowdTimer.ID, 10);
                ParentClass->Score += 7;
            }
        } else {
            bool hitByHero = Me.MsgIsHitBy("SCRIPT_NAME_HERO")
                || (Me.MsgIsHitByAnySpecialAbilityFrom("SCRIPT_NAME_HERO") && !Me.MsgIsHitBySpecialAbilityFrom(14, "SCRIPT_NAME_HERO"));
            if (hitByHero) {
                if (IsActiveThreadTerminating()) return;
                ++ParentClass->Score;
                Game->GiveThingBestEnemyTarget(Me, Game->GetHero());
            } else {
                bool hitByWhisper = Me.MsgIsHitBy("WhisperAlly") || Me.MsgIsHitByAnySpecialAbilityFrom("WhisperAlly");
                if (hitByWhisper) {
                    if (IsActiveThreadTerminating()) return;
                    Game->GiveThingBestEnemyTarget(Me, Game->GetThingWithScriptName("WhisperAlly"));
                }
            }
        }
        Game->NewScriptFrame();
    } while (!IsActiveThreadTerminating());
}

